def validate_oge23_bank():
    assert len(OGE23_BANK) == 27
    seen=set()
    for task in OGE23_BANK:
        tid=int(task["id"])
        assert 1 <= tid <= 27 and tid not in seen
        seen.add(tid)
        assert len(task["bottles"]) == 2
        assert len(task["reagents"]) == 3
        assert len(task["correct_reagents"]) == 2
        assert len(task["experiments"]) == 2
        offered={x["id"] for x in task["reagents"]}
        assert set(task["correct_reagents"]).issubset(offered)
        for exp in task["experiments"]:
            assert exp["reagent"] in offered
            assert exp["target_bottle"] in (1,2)
            assert exp["molecular"] and exp["full_ionic"] and exp["net_ionic"]
    return {"tasks":len(OGE23_BANK),"first":min(seen),"last":max(seen)}
